#!/usr/bin/env python3
"""extract_stub.py: pull .text and the stub_entry offset out of stub.obj,
emit stub_blob.h for inclusion by the BOF and the C# assembly.

Fails loudly on: non-x64 COFF, any relocation against .text (the stub must be
fully inlined; raw loads cannot resolve REL32 fixups), or a missing
stub_entry symbol.
"""
import struct
import sys


def fail(msg):
    print(f"extract_stub: ERROR: {msg}", file=sys.stderr)
    sys.exit(1)


# sizeof(ABE_PARAMS) per abe_common.h (pack(8), C_ASSERT'd in abe.c).
# Single source of truth for BOTH generated files; the browser-crash bug
# (stub walk-off) came from this value being 0x78 in the C# emitter while the
# real struct is 0x80: the candidate chain then overlapped the ncand field.
PARAMS_SIZE = 0x80


def main():
    if len(sys.argv) != 3:
        print(f"usage: {sys.argv[0]} <stub.obj> <stub_blob.h>", file=sys.stderr)
        sys.exit(2)

    obj_path, out_path = sys.argv[1], sys.argv[2]
    data = open(obj_path, "rb").read()

    (machine, nsec, _ts, sym_ptr, nsyms,
     _opt, _chars) = struct.unpack_from("<HHIIIHH", data, 0)
    if machine != 0x8664:
        fail(f"not x64 COFF (machine={machine:#x})")

    # --- section headers -------------------------------------------------
    sections = []
    off = 20
    for _ in range(nsec):
        name = data[off:off + 8].rstrip(b"\x00").decode("ascii")
        (vsize, vaddr, rawsize, rawptr, relptr, _lnptr, nrel, _nln,
         _chars) = struct.unpack_from("<IIIIIIHHI", data, off + 8)
        sections.append({
            "name": name, "vsize": vsize, "vaddr": vaddr,
            "rawsize": rawsize, "rawptr": rawptr,
            "relptr": relptr, "nrel": nrel,
        })
        off += 40

    # --- symbol table (drives section selection: MSVC splits .text into
    # .text$mn COMDAT fragments per function; stub_entry's fragment is the
    # one that ships) -------------------------------------------------------
    strtab = sym_ptr + nsyms * 18

    def sym_name(idx):
        raw = data[sym_ptr + idx * 18: sym_ptr + idx * 18 + 8]
        if raw[:4] == b"\x00\x00\x00\x00":
            stroff = struct.unpack("<I", raw[4:])[0]
            end = data.index(b"\x00", strtab + stroff)
            return data[strtab + stroff: end].decode("ascii", "replace")
        return raw.rstrip(b"\x00").decode("ascii", "replace")

    entry = None
    entry_sec = None
    seen = []
    for i in range(nsyms):
        (value, secnum, _typ, _cls,
         aux) = struct.unpack_from("<IhHBB", data, sym_ptr + i * 18 + 8)
        name = sym_name(i)
        if aux:
            i += aux  # skip auxiliary records
        seen.append((name, secnum, value))
        if name == "stub_entry":
            entry = value
            entry_sec = secnum - 1

    if entry is None:
        fail(f"stub_entry symbol not found; symbols: {seen}")
    if entry_sec < 0 or entry_sec >= nsec:
        fail(f"stub_entry section index {entry_sec} out of range")

    text_idx = entry_sec
    text = sections[text_idx]
    if not text["name"].startswith(".text"):
        fail(f"stub_entry landed in '{text['name']}'; expected a .text fragment")
    if text["nrel"] != 0:
        rels = []
        for r in range(text["nrel"]):
            va, symidx, rtype = struct.unpack_from("<IIH", data,
                                                   text["relptr"] + r * 10)
            rels.append(f"  va={va:#x} sym={symidx} type={rtype}")
        fail(f".text fragment carries {text['nrel']} relocation(s); stub must "
             f"be a single fully-inlined function:\n" + "\n".join(rels))
    if text["rawsize"] < text["vsize"]:
        fail("rawsize < vsize; unexpected for object sections")
    blob = data[text["rawptr"]:text["rawptr"] + text["rawsize"]]

    # --- emit -------------------------------------------------------------
    hexbytes = ",".join(f"0x{b:02x}" for b in blob)
    lines = []
    lines.append("// stub_blob.h: generated by extract_stub.py; do not edit")
    lines.append("#ifndef STUB_BLOB_H")
    lines.append("#define STUB_BLOB_H")
    lines.append("")
    lines.append(f"#define STUB_BLOB_SIZE       {len(blob)}")
    lines.append(f"#define STUB_ENTRY_OFFSET    {entry}")
    lines.append("/* sizeof(ABE_PARAMS) per abe_common.h pack(8); C# Marshal")
    lines.append("   layout must match exactly; verified by C_ASSERT in abe.c */")
    lines.append(f"#define STUB_PARAMS_SIZE     0x{PARAMS_SIZE:x}")
    lines.append("")
    lines.append(f"static const unsigned char stub_blob[{len(blob)}] = {{")
    for i in range(0, len(blob), 16):
        chunk = ",".join(f"0x{b:02x}" for b in blob[i:i + 16])
        lines.append(f"    {chunk},")
    lines.append("};")
    lines.append("")
    lines.append("#endif /* STUB_BLOB_H */")
    open(out_path, "w").write("\n".join(lines) + "\n")

    # --- emit C# companion (for the execute-assembly variant) -------------
    cs_path = out_path.replace("stub_blob.h", "AppBound0Stub.cs")
    cs = []
    cs.append("// AppBound0Stub.cs: generated by extract_stub.py; do not edit")
    cs.append("namespace Abe")
    cs.append("{")
    cs.append("    internal static class AppBound0Stub")
    cs.append("    {")
    cs.append(f"        public const int BlobSize = {len(blob)};")
    cs.append(f"        public const int EntryOffset = {entry};")
    cs.append(f"        // sizeof(ABE_PARAMS), pack(8); must match StubParams Marshal layout")
    cs.append("        public const int ParamsSize = 0x80;")
    cs.append("        public const int CandidateSize = 0x28;")
    cs.append("")
    cs.append(f"        public static readonly byte[] Blob = new byte[{len(blob)}]")
    cs.append("        {")
    for i in range(0, len(blob), 16):
        chunk = ",".join(f"0x{b:02x}" for b in blob[i:i + 16])
        cs.append(f"            {chunk},")
    cs.append("        };")
    cs.append("    }")
    cs.append("}")
    open(cs_path, "w").write("\n".join(cs) + "\n")

    print(f"extract_stub: OK .text={len(blob)}B entry=+{entry:#x} "
          f"(relocs=0, machine=x64) -> {out_path}, {cs_path}")


if __name__ == "__main__":
    main()
